  const kind = document.body.dataset.chapterKind || '';
  let chart = null;
  const n = (id) => { const value = Number($(id)?.value); return Number.isFinite(value) ? value : NaN; };
  const s = (id) => String($(id)?.value || '').trim();
  const checked = (id) => Boolean($(id)?.checked);
  const fmt = (value, digits = 2) => Number.isFinite(Number(value)) ? Number(value).toLocaleString('zh-TW', { minimumFractionDigits: digits, maximumFractionDigits: digits }) : '—';
  const pct = (value, digits = 2) => Number.isFinite(Number(value)) ? `${fmt(Number(value) * 100, digits)}%` : '—';
  const money = (value, digits = 0) => Number.isFinite(Number(value)) ? Number(value).toLocaleString('zh-TW', { minimumFractionDigits: digits, maximumFractionDigits: digits }) : '—';
  const requireNums = (ids) => { const missing = ids.filter((id) => !Number.isFinite(n(id))); if (missing.length) throw new Error(`請完整填寫：${missing.join('、')}`); };
  const setStatus = (main, detail, error = false) => { const el = $('chapter-status'); el?.classList.toggle('is-error', error); if ($('chapter-status-main')) $('chapter-status-main').textContent = main; if ($('chapter-status-detail')) $('chapter-status-detail').textContent = detail; };
